# Create a completely new function with fresh syntax
def transform_final(grid):
    """Transform that copies horizontal segments to all vertical bar rows"""
    h = len(grid)
    w = len(grid[0])
    best_col = -1
    best_run = 0
    for c in range(w):
        r = 0
        for r_idx in range(h):
            if grid[r_idx][c] == 5:
                r += 1
            else:
                r = 0
        if r > best_run:
            best_run = r
            best_col = c
    if best_col < 0 or best_run < 3:
        return grid
    vs = [r for r in range(h) if grid[r][best_col] == 5]
    src = None
    for v in vs:
        pp = best_col + 1
        while pp < w and grid[v][pp] == 0:
            pp += 1
        if pp < w:
            src = v
            break
    if src is None:
        return grid
    segs = []
    c = best_col + 1
    while c < w:
        if grid[src][c] > 0:
            col_col = 5
            st = c
            end = c
            while end < w - 1 and grid[src][end + 1] == col_col:
                end += 1
            if end >= st + 1:
                segs.append((st, end))
            c = end + 1
        else:
            c += 1
    print(f"Segments: {segs}")
